def cifrar(texto, k):
    resultado = ""
    for c in texto:
        if "a" <= c <= "z":
            posicao = (ord(c) - ord("a") + k) % 26
            resultado += chr(posicao + ord("a"))
        elif "A" <= c <= "Z":
            posicao = (ord(c) - ord("A") + k) % 26
            resultado += chr(posicao + ord("A"))
        else:
            resultado += c
    return resultado


def decifrar(texto, k):
    return cifrar(texto, -k)

