def dependencias_fixas(texto):
    versoes = {}
    for linha in texto.splitlines():
        linha = linha.strip()
        if linha == "" or linha.startswith("#"):
            continue
        if "==" not in linha:
            raise ValueError(f"sem versão fixa: {linha}")
        nome, versao = linha.split("==")
        versoes[nome.strip().lower()] = versao.strip()
    return versoes

