            salvo = json.load(arquivo)
    except (FileNotFoundError, json.JSONDecodeError):
        return resultado
    if not isinstance(salvo, dict):
        return resultado
    for chave in padrao:
        if chave in salvo:
            resultado[chave] = salvo[chave]
    return resultado

