from itertools import islice


class CicloDeCores:
    def __init__(self, cores):
        if not cores:
            raise ValueError("a lista de cores está vazia")
        self.cores = list(cores)
        self.indice = 0

    def __iter__(self):
        return self

    def __next__(self):
        cor = self.cores[self.indice % len(self.cores)]
        self.indice += 1
        return cor


def escala(cores, n):
    return list(islice(CicloDeCores(cores), n))

