def simular_git(comandos):
    modificados = set()
    preparados = set()
    commits = 0
    for comando in comandos:
        partes = comando.split()
        if partes[0] == "editar":
            modificados.add(partes[1])
        elif partes[:2] == ["git", "add"]:
            if partes[2] == ".":
                novos = set(modificados)
            else:
                novos = modificados & {partes[2]}
            preparados |= novos
            modificados -= novos
        elif partes[:2] == ["git", "commit"]:
            if preparados:
                commits += 1
                preparados = set()
