from datetime import datetime
from functools import wraps

NIVEIS = ("DEBUG", "INFO", "WARNING", "ERROR")
METODOS = ("GET", "POST", "PUT", "DELETE")
FORMATO_MOMENTO = "%Y-%m-%dT%H:%M:%S"

