def classificar_funcao(mapa, contradominio):
    valores = list(mapa.values())
    imagem = set(valores)
    c = set(contradominio)
    if not imagem <= c:
        raise ValueError("valor fora do contradomínio")
    injetora = len(imagem) == len(valores)
    sobrejetora = imagem == c
    if injetora and sobrejetora:
        return "bijetora"
    if injetora:
        return "injetora"
    if sobrejetora:
        return "sobrejetora"
    return "nenhuma"


