import time


def medir(funcao, entrada, repeticoes=5, relogio=time.perf_counter):
    tempos = []
    for _ in range(repeticoes):
        inicio = relogio()
        funcao(entrada)
        tempos.append(relogio() - inicio)
    return sum(tempos) / len(tempos)

