def combinacoes(lista, k):
    n = len(lista)
    resultado = []
    caminho = []

    def explorar(inicio):
        if len(caminho) == k:
            resultado.append(caminho[:])
            return
        if len(caminho) + (n - inicio) <= k:
            return
        for j in range(inicio, n):
