def n_rainhas(n):
    usado = [False] * n
    cols = []
    total = 0

    def sem_ataque():
        for i in range(n):
            for j in range(i + 1, n):
                if abs(cols[i] - cols[j]) == j - i:
                    return False
        return True

    def posicionar(linha):
        nonlocal total
        if linha == n:
            if sem_ataque():
                total += 1
            return
        for col in range(n):
            if not usado[col]:
                usado[col] = True
                cols.append(col)
                posicionar(linha + 1)
                cols.pop()
                usado[col] = False

    posicionar(0)
    return total


def soma_subconjuntos(numeros, alvo):
    v = sorted(numeros)
    resultado = []
    caminho = []

    def buscar(inicio, soma):
        if soma == alvo:
            resultado.append(caminho[:])
            return
        for j in range(inicio, len(v)):
            if soma + v[j] > alvo:
                break
            caminho.append(v[j])
            buscar(j + 1, soma + v[j])
            caminho.pop()

    buscar(0, 0)
    return resultado

