def raiz_inteira(n):
    lo = 0
    hi = n
    resposta = 0
    while lo <= hi:
        meio = (lo + hi) // 2
        if meio * meio <= n:
            resposta = meio
            lo = meio + 1
        else:
            hi = meio - 1
    return resposta


def menor_capacidade(pesos, dias):
    def consegue(cap):
        dias_usados = 1
        carga = 0
        for p in pesos:
            if carga + p > cap:
                dias_usados += 1
                carga = p
            else:
                carga += p
        return dias_usados <= dias

    lo = max(pesos)
    hi = sum(pesos)
    while lo < hi:
        meio = (lo + hi) // 2
        if consegue(meio):
            hi = meio
        else:
            lo = meio + 1
    return lo

