def bubble_sort(lista):
    n = len(lista)
    passagens = 0
    for i in range(n - 1):
        trocou = False
        passagens += 1
        for j in range(n - 1 - i):
            if lista[j] > lista[j + 1]:
                lista[j], lista[j + 1] = lista[j + 1], lista[j]
                trocou = True
        if not trocou:
            break
    return passagens


def contar_comparacoes_insertion(lista):
    v = list(lista)
    comparacoes = 0
    for i in range(1, len(v)):
        chave = v[i]
        j = i - 1
        while j >= 0:
            comparacoes += 1
            if v[j] > chave:
                v[j + 1] = v[j]
                j -= 1
            else:
                break
        v[j + 1] = chave
    return comparacoes


def contar_trocas_selection(lista):
    v = list(lista)
    n = len(v)
    trocas = 0
    for i in range(n - 1):
        idx_min = i
        for j in range(i + 1, n):
            if v[j] < v[idx_min]:
                idx_min = j
        if idx_min != i:
            v[i], v[idx_min] = v[idx_min], v[i]
            trocas += 1
    return trocas

