    for i, valor in enumerate(lista):
        if d and d[0] <= i - k:
            d.popleft()
        while d and lista[d[-1]] <= valor:
            d.pop()
        d.append(i)
        if i >= k - 1:
            resposta.append(lista[d[0]])
    return resposta

