    return lento.valor


def intercalar(a, b):
    sentinela = No(None)
    cauda = sentinela
    while a is not None and b is not None:
        if a.valor <= b.valor:
            cauda.proximo = a
            a = a.proximo
        else:
            cauda.proximo = b
            b = b.proximo
        cauda = cauda.proximo
    cauda.proximo = a if a is not None else b
    return sentinela.proximo

