from collections import OrderedDict
class Ref:
    def __init__(self, c):
        self.c = c
        self.d = OrderedDict()
    def get(self, k):
        if k not in self.d:
            return None
        self.d.move_to_end(k)
        return self.d[k]
    def put(self, k, v):
        if k in self.d:
            self.d.move_to_end(k)
            self.d[k] = v
            return
        if len(self.d) == self.c:
            self.d.popitem(last=False)
        self.d[k] = v
