from collections import deque

from arvore import No


def pos_ordem(raiz):
    if raiz is None:
        return []
    return pos_ordem(raiz.esq) + pos_ordem(raiz.dir) + [raiz.valor]


def em_ordem_iterativa(raiz):
    saida = []
    pilha = []
    atual = raiz
    while pilha or atual is not None:
        while atual is not None:
            pilha.append(atual)
            atual = atual.esq
        no = pilha.pop()
        saida.append(no.valor)
        atual = no.dir
    return saida


def por_niveis(raiz):
    if raiz is None:
        return []
    niveis = []
    fila = deque([raiz])
    while fila:
        nivel = []
        for _ in range(len(fila)):
            no = fila.popleft()
            nivel.append(no.valor)
            if no.esq is not None:
                fila.append(no.esq)
            if no.dir is not None:
                fila.append(no.dir)
        niveis.append(nivel)
    return niveis

