import heapq

FIM = object()


class FilaDePrioridade:
    def __init__(self):
        self._heap = []
        self._contador = 0

    def __len__(self):
        return len(self._heap)

    def inserir(self, prioridade, item):
        heapq.heappush(self._heap, (prioridade, self._contador, item))
        self._contador += 1

    def remover(self):
        if not self._heap:
            raise IndexError("fila vazia")
        return heapq.heappop(self._heap)[2]


def k_maiores(valores, k):
    if k <= 0:
        return []
    h = []
    for x in valores:
        if len(h) < k:
            heapq.heappush(h, x)
        elif x > h[0]:
            heapq.heapreplace(h, x)
    saida = []
    while h:
        saida.append(heapq.heappop(h))
    saida.reverse()
    return saida


def fundir(fontes, m):
    iteradores = [iter(f) for f in fontes]
    h = []
    for i, it in enumerate(iteradores):
        x = next(it, FIM)
        if x is not FIM:
            h.append((x, i))
    heapq.heapify(h)
    saida = []
    while h and len(saida) < m:
        x, i = heapq.heappop(h)
        saida.append(x)
        prox = next(iteradores[i], FIM)
        if prox is not FIM:
            heapq.heappush(h, (prox, i))
    return saida

