        if len(h) < k:
            heapq.heappush(h, x)
        elif x > h[0]:
            heapq.heapreplace(h, x)
    saida = []
    while h:
        saida.append(heapq.heappop(h))
    saida.reverse()
    return saida


def fundir(fontes, m):
    h = []
    for f in fontes:
        it = iter(f)
        x = next(it, FIM)
        if x is not FIM:
            h.append((x, it))
    heapq.heapify(h)
    saida = []
    while h and len(saida) < m:
        x, it = heapq.heappop(h)
        saida.append(x)
        prox = next(it, FIM)
        if prox is not FIM:
            heapq.heappush(h, (prox, it))
    return saida

