    def __init__(self):
        self.raiz = None

    def inserir(self, valor):
        self.raiz = self._inserir(self.raiz, valor)

    def _inserir(self, no, valor):
        if no is None:
            return NoAVL(valor)
        if valor < no.valor:
            no.esq = self._inserir(no.esq, valor)
        elif valor > no.valor:
            no.dir = self._inserir(no.dir, valor)
        else:
            return no
        atualizar_altura(no)
        return balancear(no)

    def altura(self):
        return altura_no(self.raiz)

    def em_ordem(self):
        saida = []

        def visitar(no):
            if no is not None:
                visitar(no.esq)
                saida.append(no.valor)
                visitar(no.dir)

        visitar(self.raiz)
        return saida

