from collections import deque


def eh_bipartido(grafo):
    cor = {}
    for inicio in grafo:
        if inicio in cor:
            continue
        cor[inicio] = 0
        fila = deque([inicio])
        while fila:
            u = fila.popleft()
            for v in grafo[u]:
                if v not in cor:
                    cor[v] = 1 - cor[u]
                    fila.append(v)
                elif cor[v] == cor[u]:
                    return False
    return True


def contar_ilhas(grade):
    linhas = len(grade)
    colunas = len(grade[0]) if grade else 0
    vistos = set()
    ilhas = 0
    for i in range(linhas):
        for j in range(colunas):
            if grade[i][j] != "#" or (i, j) in vistos:
                continue
            ilhas += 1
            vistos.add((i, j))
            pilha = [(i, j)]
            while pilha:
                a, b = pilha.pop()
                for da, db in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    x, y = a + da, b + db
                    if 0 <= x < linhas and 0 <= y < colunas and grade[x][y] == "#" and (x, y) not in vistos:
                        vistos.add((x, y))
                        pilha.append((x, y))
    return ilhas

