from collections import deque


def ordem_topologica(grafo):
    grau = {v: 0 for v in grafo}
    for u in grafo:
        for v in grafo[u]:
            grau[v] += 1
    fila = deque(v for v in grafo if grau[v] == 0)
    ordem = []
    while fila:
        u = fila.popleft()
        ordem.append(u)
        for v in grafo[u]:
            grau[v] -= 1
            if grau[v] == 0:
                fila.append(v)
    if len(ordem) < len(grafo):
        return None
    return ordem

