import heapq


def dijkstra(grafo, origem):
    dist = {origem: 0}
    heap = [(0, origem)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, peso in grafo[u]:
            nova = d + peso
            if v not in dist or nova < dist[v]:
                dist[v] = nova
                heapq.heappush(heap, (nova, v))
    return dist


def caminho_minimo(grafo, origem, destino):
    dist = {origem: 0}
    pred = {origem: None}
    heap = [(0, origem)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == destino:
            break
        for v, peso in grafo[u]:
            nova = d + peso
            if v not in dist or nova < dist[v]:
                dist[v] = nova
                pred[v] = u
                heapq.heappush(heap, (nova, v))
    if destino not in dist:
        return None
    caminho = []
    v = destino
    while v is not None:
        caminho.append(v)
        v = pred[v]
    caminho.reverse()
    return dist[destino], caminho

