import heapq

from uf import UnionFind


def prim(grafo, inicio):
    na_arvore = {inicio}
    heap = [(peso, v) for v, peso in grafo[inicio]]
    heapq.heapify(heap)
    custo = 0
    while heap:
        peso, v = heapq.heappop(heap)
        if v in na_arvore:
            continue
        na_arvore.add(v)
        custo += peso
        for w, p in grafo[v]:
            if w not in na_arvore:
                heapq.heappush(heap, (p, w))
    return custo


def agrupar(pontos, k):
    n = len(pontos)
    pares = []
    for i in range(n):
        for j in range(i + 1, n):
            (x1, y1), (x2, y2) = pontos[i], pontos[j]
            pares.append(((x1 - x2) ** 2 + (y1 - y2) ** 2, i, j))
    pares.sort()
    uf = UnionFind(n)
    for _, i, j in pares:
        if uf.conjuntos <= k:
            break
        uf.unir(i, j)
    grupos = {}
    for i in range(n):
        grupos.setdefault(uf.encontrar(i), []).append(i)
    return sorted(grupos.values())

