    uf = UnionFind(n)
    for i, j, _ in pares:
        if uf.conjuntos <= k:
            break
        uf.unir(i, j)
    grupos = {}
    for i in range(n):
        grupos.setdefault(uf.encontrar(i), []).append(i)
    return sorted(grupos.values())

