def troco_minimo(moedas, valor):
    memo = {}

    def melhor(v):
        if v == 0:
            return (0, None)
        if v in memo:
            return memo[v]
        resposta = None
        for m in moedas:
            if m <= v:
                sub = melhor(v - m)
                if sub is not None and (resposta is None or sub[0] + 1 < resposta[0]):
                    resposta = (sub[0] + 1, m)
        memo[v] = resposta
        return resposta

    if melhor(valor) is None:
        return None
    escolhidas = []
    v = valor
    while v > 0:
        m = melhor(v)[1]
        escolhidas.append(m)
        v -= m
    return sorted(escolhidas, reverse=True)

