def maximo_de_atividades(pedidos):
    escolhidos = []
    for inicio, fim in sorted(pedidos, key=lambda p: p[1] - p[0]):
        if all(inicio >= f or fim <= i for i, f in escolhidos):
            escolhidos.append((inicio, fim))
