import heapq


def alcancaveis(mapa, origem, limite):
    dist = {origem: 0}
    heap = [(0, origem)]
    resposta = []
    while heap:
        d, local = heapq.heappop(heap)
        if d > dist[local]:
            continue
        resposta.append((d, local))
        for vizinho, minutos, _ in mapa["vizinhos"][local]:
            nova = d + minutos
