    def melhor(i, livre):
        if i == len(tarefas):
            return 0, []
        sem = melhor(i + 1, livre)
        if custos[i] is not None and custos[i] <= livre:
            valor, nomes = melhor(i + 1, livre - custos[i])
            if valor + tarefas[i][3] > sem[0]:
