def prever_shape(forma_a, forma_b):
    n = max(len(forma_a), len(forma_b))
    a = (1,) * (n - len(forma_a)) + tuple(forma_a)
    b = (1,) * (n - len(forma_b)) + tuple(forma_b)
    resultado = []
    for x, y in zip(a, b):
        if x == y or y == 1:
            resultado.append(x)
        elif x == 1:
            resultado.append(y)
        else:
            return None
    return tuple(resultado)

