def classificar_risco(df):
    condicoes = [(df["atraso"] > 60) | (df["divida"] > 5000), df["atraso"] > 15]
    rotulos = ["alto", "médio"]
    return pd.Series(np.select(condicoes, rotulos, default="baixo"), index=df.index)

