import pandas as pd


def comparar_grupos(df, valor, grupo):
    g = df.groupby(grupo)[valor]
    tabela = pd.DataFrame({
        "n": g.count(),
        "mediana": g.median(),
        "iqr": g.quantile(0.75) - g.quantile(0.25),
    })
    return tabela.to_dict("index")

