def atributos_colineares(X):
    X = np.asarray(X, dtype=float)
    d = X.shape[1]
    if d < 2:
        return False
    r = np.corrcoef(X.T)[np.triu_indices(d, 1)]
    return bool(np.any(np.abs(r) > 0.999999))

