import numpy as np
rng = np.random.default_rng(8)
X = np.vstack([rng.normal(0, 1, (40, 2)), rng.normal(1.2, 0.8, (12, 2))]).round(3)
y = np.array([0] * 40 + [1] * 12)
def no_segmento(Xo, yo, sint, k):
    Xm = Xo[yo == 1]
    d = np.linalg.norm(Xm[:, None, :] - Xm[None, :, :], axis=2)
    viz = np.argsort(d, axis=1)[:, 1:k + 1]
    ok = []
    for s in sint:
        achou = False
        for a in range(len(Xm)):
            for b in viz[a]:
                v = Xm[b] - Xm[a]
                t = float((s - Xm[a]) @ v / (v @ v))
                if -1e-9 <= t <= 1 + 1e-9 and np.linalg.norm(Xm[a] + t * v - s) < 1e-9:
                    achou = True
        ok.append(achou)
    return all(ok)
