import numpy as np

W1 = np.array([[1.0, 1.0], [1.0, 1.0]])
b1 = np.array([-0.5, -1.5])
w2 = np.array([1.0, -1.0])
b2 = -0.5


def degrau(z):
    return (z > 0).astype(int)


def camada_escondida(X):
    X = np.asarray(X, dtype=float)
    return degrau(X @ W1 + b1)


def rede_xor(X):
    H = camada_escondida(X)
    return degrau(H @ w2 + b2)

