        return _sigmoide(logits)
    if tarefa == "multiclasse":
        Z = logits - logits.max(axis=1, keepdims=True)
        E = np.exp(Z)
        return E / E.sum(axis=1, keepdims=True)
    if tarefa == "regressao":
        return logits.copy()
    return None

