def _num(f, xs, h=1e-6):
    out = []
    for i in range(len(xs)):
        mais, menos = list(xs), list(xs)
        mais[i] += h
        menos[i] -= h
        out.append((f(*[Valor(x) for x in mais]).dado - f(*[Valor(x) for x in menos]).dado) / (2 * h))
    return out
def _confere(f, xs):
    vs = [Valor(x) for x in xs]
    f(*vs).backward()
    return [abs(v.grad - n) < 1e-6 * max(1.0, abs(n)) for v, n in zip(vs, _num(f, xs))]
def f(a, b):
    return (a * a + b) / (b - a)

