        return base * (passo + 1) / aquecimento
    k = passo - aquecimento
    n = total - aquecimento
    if tipo == "degraus":
        return base * 0.1 ** (3 * k // n)
    if tipo == "cosseno":
        return base * 0.5 * (1 + math.cos(math.pi * k / (n - 1)))
    return base

