    total = 0
    for camada in camadas:
        if camada["tipo"] == "conv":
            total += camada["k"] * camada["k"] * camada["entrada"] * camada["saida"] + camada["saida"]
        elif camada["tipo"] == "densa":
            total += 0
    return total

