import json


class ErroDeSchema(Exception):
    pass


def tipo_confere(valor, tipo):
    if isinstance(valor, bool):
        return tipo is bool
    if tipo is float:
        return isinstance(valor, (int, float))
    return isinstance(valor, tipo)


