        self.docs = [Counter(tokenizar(t)) for t in textos]
        self.tamanhos = [sum(c.values()) for c in self.docs]
        self.n = len(self.docs)
        self.media = sum(self.tamanhos) / self.n if self.n else 0.0
        self.df = Counter()
