                    s += self.idf(termo) * tf * (self.k1 + 1) / (tf + self.k1 * norma)
            scores.append(s)
        return scores


def top_k(scores, k):
    s = np.asarray(scores, dtype=float)
    k = min(k, len(s))
    if k <= 0:
        return []
