            soma += len(achados & set(caso["relevantes"])) / len(caso["relevantes"])
        recall[nome] = round(soma / len(conjunto), 4)
    melhor = ESTRATEGIAS[0]
    for nome in ESTRATEGIAS:
        if recall[nome] > recall[melhor]:
            melhor = nome
    return {"recall": recall, "melhor": melhor}


