def sem_acento(texto):
    return unicodedata.normalize("NFKD", texto.lower()).encode("ascii", "ignore").decode()


def tema(texto):
    for palavra in re.findall(r"[a-z0-9]+", sem_acento(texto)):
        if palavra in TEMAS:
            return TEMAS[palavra]
    return None


