            pergunta = linha[len("Pergunta atual:"):].strip()
    termos = re.findall(r"[a-z0-9]+", sem_acento(pergunta))
    depende = termos[:1] == ["e"] or any(t in REFERENCIAS for t in termos)
    if tema(pergunta) or not depende:
        return pergunta
