                    self.eventos.append({"janela": janela, "evento": "disparou", "psi": psi})
            else:
                self._seguidas = 0
        elif psi < self.rearme:
            self.estado = "ok"
            self._seguidas = 0
            self.eventos.append({"janela": janela, "evento": "normalizou", "psi": psi})
        return self.estado

